with base as (select * from shipments where order_id is not null), summary as (select case when cost >= 105 then 'high' when cost >= 20 then 'mid' else 'low' end as cost_bucket, round((100 * sum(case when status = 'DELIVERED' then 1 else 0 end)) / count(*), 1) as pct_delivered, avg(cost) as avg_cost from base group by case when cost >= 105 then 'high' when cost >= 20 then 'mid' else 'low' end) select cost_bucket, pct_delivered, avg_cost from summary
